WITH scored AS (SELECT *, LAG(duration_sec) OVER w_hist AS prev_duration_sec, LEAD(duration_sec) OVER w_hist AS next_duration_sec, ROW_NUMBER() OVER w_hist AS seq_no, AVG(duration_sec) OVER (PARTITION BY session_id ORDER BY duration_sec, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS duration_sec_avg_3 FROM web_events WINDOW w_hist AS (PARTITION BY session_id ORDER BY event_time, id)) SELECT id, event_type, page, duration_sec, prev_duration_sec, next_duration_sec, seq_no, CASE WHEN event_type RLIKE '^(page_view|add_to_cart)$' THEN 'CORE' ELSE 'OTHER_ZONE' END AS event_type_zone FROM scored ORDER BY id DESC
